CREATE UNIQUE INDEX screen_name_lower_uq ON public.screen(lower(name));
CREATE FUNCTION public.get_my_bookings() RETURNS TABLE(booking_id uuid,booking_no text,status text,category text,movie_title text,screen_name text,starts_at timestamptz,seat_labels text[],seat_count int,total_amount int,has_discount boolean,booked_at timestamptz,cancelled_at timestamptz,refund_amount int,cancel_deadline timestamptz,can_cancel boolean) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'NOT_LOGGED_IN: Please log in to continue.'; END IF; RETURN QUERY SELECT b.id,b.booking_no,b.status,CASE WHEN b.status='CANCELLED' THEN 'CANCELLED' WHEN now()>=ss.starts_at THEN 'PAST' ELSE 'UPCOMING' END,m.title,sc.name,ss.starts_at,array_agg(s.row_label||s.col_no ORDER BY s.row_index,s.col_no),count(bs.id)::int,b.total_amount,bool_or(bs.is_discounted),b.booked_at,b.cancelled_at,b.refund_amount,ss.starts_at-interval '20 minutes',b.status='CONFIRMED' AND now()<=ss.starts_at-interval '20 minutes' FROM public.booking b JOIN public.screening ss ON ss.id=b.screening_id JOIN public.movie m ON m.id=ss.movie_id JOIN public.screen sc ON sc.id=ss.screen_id JOIN public.booking_seat bs ON bs.booking_id=b.id JOIN public.seat s ON s.id=bs.seat_id WHERE b.member_id=auth.uid() GROUP BY b.id,ss.starts_at,m.title,sc.name ORDER BY ss.starts_at; END $$;
CREATE FUNCTION public.cancel_booking(p_booking_id uuid) RETURNS TABLE(booking_no text,refund_amount int,cancelled_at timestamptz) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_booking public.booking%ROWTYPE; v_start timestamptz; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'NOT_LOGGED_IN: Please log in to continue.'; END IF; SELECT b.* INTO v_booking FROM public.booking b WHERE b.id=p_booking_id AND b.member_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'NOT_OWNER: This booking was not found.'; END IF; PERFORM pg_advisory_xact_lock(hashtext(v_booking.screening_id::text)); SELECT b.* INTO v_booking FROM public.booking b WHERE b.id=p_booking_id AND b.member_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'NOT_OWNER: This booking was not found.'; END IF; IF v_booking.status='CANCELLED' THEN RAISE EXCEPTION 'ALREADY_CANCELLED: This booking has already been cancelled.'; END IF; SELECT ss.starts_at INTO v_start FROM public.screening ss WHERE ss.id=v_booking.screening_id; IF now()>v_start-interval '20 minutes' THEN RAISE EXCEPTION 'CANCEL_CLOSED: Cancellation closes 20 minutes before the screening starts.'; END IF; UPDATE public.booking b SET status='CANCELLED',cancelled_at=now(),refund_amount=b.total_amount WHERE b.id=p_booking_id; UPDATE public.booking_seat bs SET is_active=false WHERE bs.booking_id=p_booking_id; RETURN QUERY SELECT v_booking.booking_no,v_booking.total_amount,now(); END $$;
CREATE FUNCTION public.configure_screen(p_name text,p_b1_rows int,p_b1_cols int,p_b2_rows int,p_b2_cols int,p_b3_rows int,p_b3_cols int) RETURNS TABLE(screen_id uuid,seats_created int,max_seats int) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_name text:=btrim(p_name); v_id uuid; v_count int; v_max int; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY: Only administrators can do this.'; END IF; IF v_name IS NULL OR length(v_name)<1 OR length(v_name)>20 THEN RAISE EXCEPTION 'SCREEN_NAME_INVALID: Screen name must have 1 to 20 characters.'; END IF; IF EXISTS(SELECT 1 FROM public.screen sc WHERE lower(sc.name)=lower(v_name)) THEN RAISE EXCEPTION 'SCREEN_NAME_TAKEN: A screen with this name already exists.'; END IF; IF p_b1_rows IS NULL OR p_b2_rows IS NULL OR p_b3_rows IS NULL OR p_b1_cols IS NULL OR p_b2_cols IS NULL OR p_b3_cols IS NULL OR p_b1_rows NOT BETWEEN 0 AND 30 OR p_b2_rows NOT BETWEEN 0 AND 30 OR p_b3_rows NOT BETWEEN 0 AND 30 OR NOT(p_b1_cols=0 OR p_b1_cols BETWEEN 2 AND 20) OR NOT(p_b2_cols=0 OR p_b2_cols BETWEEN 2 AND 20) OR NOT(p_b3_cols=0 OR p_b3_cols BETWEEN 2 AND 20) THEN RAISE EXCEPTION 'BLOCK_SIZE_INVALID: Rows must be 0 to 30 and columns 0 or 2 to 20 in every block.'; END IF; v_max:=greatest(CASE WHEN p_b1_rows>0 THEN p_b1_cols ELSE 0 END,CASE WHEN p_b2_rows>0 THEN p_b2_cols ELSE 0 END,CASE WHEN p_b3_rows>0 THEN p_b3_cols ELSE 0 END); IF v_max<2 THEN RAISE EXCEPTION 'SCREEN_EMPTY: At least one block must have seats.'; END IF; INSERT INTO public.screen(name,block1_rows,block1_cols,block2_rows,block2_cols,block3_rows,block3_cols) VALUES(v_name,p_b1_rows,p_b1_cols,p_b2_rows,p_b2_cols,p_b3_rows,p_b3_cols) RETURNING id INTO v_id; v_count:=public.generate_seats(v_id); RETURN QUERY SELECT v_id,v_count,v_max; EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'SCREEN_NAME_TAKEN: A screen with this name already exists.'; END $$;
REVOKE ALL ON FUNCTION public.get_my_bookings(),public.cancel_booking(uuid),public.configure_screen(text,int,int,int,int,int,int) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_my_bookings(),public.cancel_booking(uuid),public.configure_screen(text,int,int,int,int,int,int) TO authenticated;